import{_ as a,o as t,c as n,aa as i}from"./chunks/framework.D7Mdgkg-.js";const g=JSON.parse('{"title":"AI Agent Skills","description":"An index of reusable skills for AI agents contributing to Feluqa.","frontmatter":{"requestedLanguage":"fr","contentLanguage":"en","languageFallbackNotice":"Cette page n’est pas disponible en Français. La version en anglais est affichée.","sidebarTitle":"Agents","icon":"bot","title":"AI Agent Skills","description":"An index of reusable skills for AI agents contributing to Feluqa.","summary":"Introduces reusable skills for AI agents working on Feluqa, explains how they relate to project instructions and product guides, and lists the documentation-writing skill. It also defines a portable, gitignored `.x-agents/` directory at the root of a documentation working area for local rules and planning notes.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":0,"status":"Exploring","tags":["feluqa","agents","skills"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"fr/agents/index.md","filePath":"fr/agents/index.md"}'),o={name:"fr/agents/index.md"};function s(l,e,r,d,c,u){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="ai-agent-skills" tabindex="-1">AI Agent Skills <a class="header-anchor" href="#ai-agent-skills" aria-label="Permalink to &quot;AI Agent Skills&quot;">​</a></h1><p>This guide collects reusable skills for AI agents working on Feluqa. Each skill describes a focused workflow for a recurring task, such as changing documentation or validating a subsystem.</p><p>Skills supplement applicable project instructions and relevant product or technical guides. They do not override those instructions, change the implementation status of a feature, or replace required review and validation.</p><h2 id="local-documentation-rules" tabindex="-1">Local documentation rules <a class="header-anchor" href="#local-documentation-rules" aria-label="Permalink to &quot;Local documentation rules&quot;">​</a></h2><p>An agent may keep local rules, working notes, and planning documents in a <code>.x-agents/</code> directory at the root of its working area:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;working-area-root&gt;/.x-agents/RULES.md</span></span>
<span class="line"><span>&lt;working-area-root&gt;/.x-agents/&lt;other-local-file-or-folder&gt;/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>For example, the working root for this guide collection is <code>docs/guides/feluqa.rs/</code>, so its local agent material belongs in <code>docs/guides/feluqa.rs/.x-agents/</code>. Put shared local conventions in <code>RULES.md</code>; use additional portable Markdown files for focused rules, working notes, and plans. Add the path to the working repository&#39;s <code>.gitignore</code> so these local files are not committed or published as guide pages. Keep canonical, reader-facing product and technical guidance in the published documentation tree. Follow the project owner&#39;s instructions when material is intended to be shared.</p><h2 id="documentation-for-the-published-site" tabindex="-1">Documentation for the published site <a class="header-anchor" href="#documentation-for-the-published-site" aria-label="Permalink to &quot;Documentation for the published site&quot;">​</a></h2><p>Write documentation as standalone site content. Do not link to local source files using relative paths; refer instead to files distributed with source code or to product resources, and describe unavailable resources as planned.</p><h2 id="available-skills" tabindex="-1">Available skills <a class="header-anchor" href="#available-skills" aria-label="Permalink to &quot;Available skills&quot;">​</a></h2><ul><li><a href="/fr/agents/skills/writing-docs">Writing Published Feluqa Documentation</a>: preserve product intent, use the canonical taxonomy, keep site content independent of local source files, and distinguish product direction from delivered behavior.</li></ul><p>Add a skill when a task has a repeatable workflow that benefits from dedicated instructions; keep general project rules in <code>AGENTS.md</code> and link to them instead of copying them into every skill.</p>`,12)])])}const h=a(o,[["render",s]]);export{g as __pageData,h as default};
